(function(window) {
    window.JsBarcode = function(target, text, options) {
        options = options || {};
        var width = options.width || 2;
        var height = options.height || 50;
        var element = typeof target === 'string' ? document.querySelector(target) : target;
        if (!element) return;
        
        var code128B = {
            ' ': '11011001100', '!': '11001101100', '"': '11001100110', '#': '10010011000',
            '$': '10010001100', '%': '10001001100', '&': '10011001000', "'": '10011000100',
            '(': '10001100100', ')': '11001001000', '*': '11001000100', '+': '11000100100',
            ',': '10110011100', '-': '10011011100', '.': '10011001110', '/': '10111001100',
            '0': '10011101100', '1': '10011100110', '2': '11001110100', '3': '11001110010',
            '4': '11011100100', '5': '11011011100', '6': '11011001110', '7': '11011101100',
            '8': '11011100110', '9': '11011011100', 'A': '11010010000', 'B': '11010001000',
            'C': '11010000100', 'D': '11001010000', 'E': '11001001000', 'F': '11001000100',
            'G': '11000101000', 'H': '11000100100', 'I': '10110010000', 'J': '10110001000',
            'K': '10011010000', 'L': '10011001000', 'M': '10011000100', 'N': '10001101000',
            'O': '10001100100', 'P': '10001011000', 'Q': '10001001100', 'R': '10110000100',
            'S': '10011000010', 'T': '10001100010', 'U': '11010000110', 'V': '11000100110',
            'W': '11000010010', 'X': '11000011010', 'Y': '11011000010', 'Z': '11011000100'
        };
        
        var startB = '11010010000';
        var stop = '1100011101011';
        
        var binary = startB;
        var strText = String(text || '');
        for (var i = 0; i < strText.length; i++) {
            var ch = strText[i];
            if (code128B[ch]) {
                binary += code128B[ch];
            } else {
                binary += '10011101100';
            }
        }
        binary += stop;
        
        if (element.tagName && element.tagName.toLowerCase() === 'svg') {
            element.innerHTML = '';
            var x = 10;
            for (var b = 0; b < binary.length; b++) {
                if (binary[b] === '1') {
                    var rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
                    rect.setAttribute('x', x);
                    rect.setAttribute('y', 5);
                    rect.setAttribute('width', width);
                    rect.setAttribute('height', height);
                    rect.setAttribute('fill', options.lineColor || '#0f172a');
                    element.appendChild(rect);
                }
                x += width;
            }
            if (options.displayValue) {
                var textNode = document.createElementNS('http://www.w3.org/2000/svg', 'text');
                textNode.setAttribute('x', x / 2);
                textNode.setAttribute('y', height + 20);
                textNode.setAttribute('text-anchor', 'middle');
                textNode.setAttribute('font-family', 'monospace');
                textNode.setAttribute('font-size', options.fontSize || 13);
                textNode.setAttribute('font-weight', 'bold');
                textNode.setAttribute('fill', options.lineColor || '#0f172a');
                textNode.textContent = strText;
                element.appendChild(textNode);
            }
            element.setAttribute('viewBox', '0 0 ' + (x + 10) + ' ' + (height + 25));
        }
    };
})(window);
